    "status": 200,
    "message": "Success",
    "data": [
        {
            "id": "1d768a78-be3f-4448-931d-258f436cfb98",
            "stepOrder": 1,
            "name": "Create a book",
            "type": "HTTP_REQUEST",
            "config": {
                "body": {
                    "year": 1941,
                    "title": "Dế Mèn Phiêu Lưu Ký",
                    "author": "Tô Hoài"
                },
                "path": "/api/v1/books",
                "method": "POST",
                "extract": [
                    {
                        "from": "response_body",
                        "name": "bookId",
                        "expression": "$.id"
                    }
                ],
                "headers": {
                    "Content-Type": "application/json"
                },
                "expected_status": 201
            },
            "expectedResult": null,
            "weight": 2,
            "timeoutMs": null,
            "required": true
        },
        {
            "id": "a4c94b8d-4cf3-4ca8-bd21-67949a00dc2f",
            "stepOrder": 2,
            "name": "Verify book details v2",
            "type": "HTTP_REQUEST",
            "config": {
                "path": "/api/v1/books/${bookId}",
                "method": "GET",
                "expected_status": 200,
                "expected_body_contains": "Dế Mèn Phiêu Lưu Ký"
            },
            "expectedResult": null,
            "weight": 2,
            "timeoutMs": null,
            "required": true
        },
        {
            "id": "27812688-290e-429a-b36d-f99153d4620d",
            "stepOrder": 4,
            "name": "Check DB schema",
            "type": "DB_SCHEMA_CHECK",
            "config": {
                "checks": [
                    {
                        "kind": "TABLE_EXISTS",
                        "table_name": "books"
                    },
                    {
                        "kind": "COLUMN_EXISTS",
                        "data_type": "VARCHAR",
                        "table_name": "books",
                        "column_name": "title"
                    },
                    {
                        "kind": "PRIMARY_KEY",
                        "column": "id",
                        "table_name": "books"
                    }
                ]
            },
            "expectedResult": null,
            "weight": 2,
            "timeoutMs": null,
            "required": true
        },
        {
            "id": "e002ab8f-1649-435f-a04b-10a1618e868e",
            "stepOrder": 6,
            "name": "Verify data in DB",
            "type": "DB_QUERY",
            "config": {
                "query": "SELECT title, author, year FROM books WHERE id = ${bookId}",
                "expected": {
                    "columns": [
                        "title",
                        "author",
                        "year"
                    ],
                    "row_count": 1
                }
            },
            "expectedResult": {
                "columns": [
                    "title",
                    "author",
                    "year"
                ],
                "row_count": 1
            },
            "weight": 2,
            "timeoutMs": 15000,
